-- Universal Click / Tap Handler (supports Mouse, Touch, and all Executor environments)
local function onClick(obj, callback)
    if not obj then return end
    local debounced = false
    local function fire(input)
        if debounced then return end
        debounced = true
        task.delay(0.08, function() debounced = false end)
        callback(input)
    end

    if obj:IsA("GuiButton") then
        obj.MouseButton1Click:Connect(fire)
        pcall(function() obj.Activated:Connect(fire) end)
    end
    obj.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            fire(input)
        end
    end)
end

local function makeButtonInteractive(btn, callback)
    if not btn then return end
    onClick(btn, callback)
    for _, desc in ipairs(btn:GetDescendants()) do
        if desc:IsA("GuiObject") then
            onClick(desc, callback)
        end
    end
end

