-- Draggable implementation (does not block clicks on child buttons)
local function makeDraggable(handle, object)
    if not handle or not object then return end
    handle.Active = false
    local dragging = false
    local dragInput, dragStart, startPos

    handle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            if G.Right then
                local rPos = G.Right.AbsolutePosition
                local rSize = G.Right.AbsoluteSize
                if input.Position.X >= rPos.X and input.Position.X <= rPos.X + rSize.X and
                   input.Position.Y >= rPos.Y and input.Position.Y <= rPos.Y + rSize.Y then
                    return
                end
            end

            dragging = true
            dragStart = input.Position
            startPos = object.Position

            local conn
            conn = input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                    if conn then conn:Disconnect() end
                end
            end)
        end
    end)

    handle.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            dragInput = input
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if input == dragInput and dragging then
            local delta = input.Position - dragStart
            object.Position = UDim2.new(
                startPos.X.Scale,
                startPos.X.Offset + delta.X,
                startPos.Y.Scale,
                startPos.Y.Offset + delta.Y
            )
        end
    end)
end

makeDraggable(G.Topbar, G.Frame)
makeDraggable(G.Title, G.Frame)
makeDraggable(G.Drag, G.Frame_406)

