local function switchTab(index)
    for i, tab in ipairs(tabList) do
        if tab.frame then
            if i == index then
                tab.frame.AnchorPoint = Vector2.new(0, 0)
                tab.frame.Position = UDim2.new(0, 0, 0, 0)
                tab.frame.Visible = true
            else
                tab.frame.Visible = false
            end
        end
        if tab.button then
            tab.button.ImageTransparency = (i == index) and 0.93 or 1
        end
        if tab.label then
            tab.label.TextTransparency = (i == index) and 0 or 0.3
        end
    end
end

for i, tab in ipairs(tabList) do
    if tab.button then
        makeButtonInteractive(tab.button, function()
            switchTab(i)
        end)
    end
end

switchTab(1)

