local function setupToggle(item)
    local row = item.row
    local btn = item.button
    local layer = item.layer
    local icon = item.icon
    local isOn = false

    local function updateVisual()
        local targetTransp = isOn and 0 or 1
        if layer then
            pcall(function()
                TweenService:Create(layer, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {ImageTransparency = targetTransp}):Play()
            end)
        end
        if icon then
            pcall(function()
                TweenService:Create(icon, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {ImageTransparency = targetTransp}):Play()
            end)
        end
    end

    local function toggle()
        isOn = not isOn
        updateVisual()
    end

    if btn then
        makeButtonInteractive(btn, toggle)
    end
    if row and row ~= btn then
        makeButtonInteractive(row, toggle)
    end
end

for _, item in ipairs(toggleDefinitions) do
    setupToggle(item)
end

