}

local function setupSlider(item)
    local track = item.track
    local fill = item.fill
    local thumb = item.thumb
    local textbox = item.textbox
    local minVal = item.min or 0
    local maxVal = item.max or 100
    local isFloat = item.isFloat or false
    if not track or not fill then return end

    local dragging = false

    local function updateFromPos(x)
        local width = track.AbsoluteSize.X
        if width <= 0 then width = 130 end
        local rel = math.clamp((x - track.AbsolutePosition.X) / width, 0, 1)
        fill.Size = UDim2.new(rel, 0, 1, 0)
        local val = minVal + (maxVal - minVal) * rel
        if isFloat then
            val = math.floor(val * 10) / 10
            if textbox then textbox.Text = tostring(val) end
        else
            val = math.floor(val + 0.5)
            if textbox then textbox.Text = tostring(val) end
        end
    end

    local function startDrag(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            updateFromPos(input.Position.X)
            local conn
            conn = input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                    if conn then conn:Disconnect() end
                end
            end)
        end
    end

    track.InputBegan:Connect(startDrag)
    fill.InputBegan:Connect(startDrag)
    if thumb then thumb.InputBegan:Connect(startDrag) end

    UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            updateFromPos(input.Position.X)
        end
    end)

    if textbox then
        textbox.FocusLost:Connect(function()
            local num = tonumber(textbox.Text)
            if num then
                local clamped = math.clamp(num, minVal, maxVal)
                local rel = (clamped - minVal) / (maxVal - minVal)
                fill.Size = UDim2.new(rel, 0, 1, 0)
                textbox.Text = tostring(clamped)
            else
                textbox.Text = item.initial or tostring(minVal)
            end
        end)
    end
end

for _, item in ipairs(sliderDefinitions) do
    setupSlider(item)
end

