}

local function setupDropdown(dd)
    if not dd.label then return end
    local currentIndex = 1
    for idx, opt in ipairs(dd.options) do
        if opt == dd.label.Text then
            currentIndex = idx
            break
        end
    end

    local function cycle()
        currentIndex = (currentIndex % #dd.options) + 1
        dd.label.Text = dd.options[currentIndex]
    end

    if dd.button then
        makeButtonInteractive(dd.button, cycle)
    end
    if dd.row and dd.row ~= dd.button then
        makeButtonInteractive(dd.row, cycle)
    end
end

for _, dd in ipairs(dropdownDefinitions) do
    setupDropdown(dd)
end

-- 6. Action Buttons Visual Feedback
local function setupActionButton(btn, onClickAction)
    if not btn then return end
    makeButtonInteractive(btn, function()
        pcall(function()
            local originalTransp = btn.ImageTransparency
            btn.ImageTransparency = 0.5
            task.delay(0.15, function()
                btn.ImageTransparency = originalTransp
            end)
        end)
        if onClickAction then
            pcall(onClickAction)
        end
    end)
end

local function copyJobId()
    pcall(function()
        if setclipboard then
            setclipboard(tostring(game.JobId))
        end
        if G.TextLabel_208 then
            local old = G.TextLabel_208.Text
            G.TextLabel_208.Text = "Copied!"
            task.delay(1.5, function()
                G.TextLabel_208.Text = old
            end)
        end
    end)
end

