-- Mount ScreenGui safely to appropriate container
local function getGuiParent()
    local successHui, hui = pcall(function() return gethui() end)
    if successHui and hui then
        return hui
    end
    local successCore, coreGui = pcall(function() return game:GetService("CoreGui") end)
    if successCore and coreGui and not game:GetService("RunService"):IsStudio() then
        return coreGui
    end
    return game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
end

local targetGui = getGuiParent()
